  const $=(id)=>document.getElementById(id);
  function hasLocalStudentAccount(){if(localStorage.getItem(studentAutoEntrySkip)==='1')return false;if(localStorage.getItem(studentAccountMarker)==='1')return true;for(let i=0;i<localStorage.length;i+=1){const key=localStorage.key(i)||'';if(/^vocahero_[3-6]_/.test(key))return true;}return false;}
  const toast=(message)=>typeof window.showToast==='function'?window.showToast(message):undefined;
  const alertError=(error)=>{console.error('[VocaHero]',error);let message=error?.message||'다시 시도해 주세요.';const errorCode=error?.code||'';const code=errorCode?` (${errorCode})`:'';if(errorCode==='auth/unauthorized-domain')message='현재 접속한 주소가 Google 로그인 허용 도메인에 등록되지 않았어요. 관리자에게 접속 주소를 알려 주세요.'+code;else if(errorCode==='auth/popup-blocked')message='브라우저가 Google 로그인 창을 차단했어요. 팝업을 허용한 뒤 다시 시도해 주세요.'+code;else if(errorCode==='auth/popup-closed-by-user')message='Google 로그인 창이 닫혔어요. 계정을 선택해 로그인을 완료해 주세요.';else if(errorCode==='auth/cancelled-popup-request')message='이미 Google 로그인 창을 여는 중이에요. 열린 창에서 로그인을 완료해 주세요.';else if(/_popupRedirectResolver|Firebase 인증/.test(message))message='Google 로그인 구성에 실패했어요. 페이지를 새로고침한 뒤 다시 시도해 주세요.'+code;else if(errorCode==='auth/internal-error'||errorCode==='auth/network-request-failed')message='Google 로그인 연결을 준비하지 못했어요. 네트워크를 확인한 뒤 다시 시도해 주세요.'+code;if(typeof window.showAlert==='function')window.showAlert(message,'!','알림');else window.alert(message);};  const nickname=()=>`${adjectives[Math.floor(Math.random()*adjectives.length)]}${animals[Math.floor(Math.random()*animals.length)]}${Math.floor(10+Math.random()*90)}`;
