  async function activeStudentAuth(requireGoogle=false){for(let attempt=0;attempt<100;attempt+=1){const basicReady=window._fbReady&&window._fbAuth&&window._signInWithPopup&&window._fbSignInAnonymously;const googleReady=!requireGoogle||(window._fbStudentGoogleProvider&&window._fbLinkWithPopup&&window._fbUnlink&&window._fbReauthenticateWithPopup);if(basicReady&&googleReady)return window._fbAuth;await new Promise(resolve=>setTimeout(resolve,100));}throw new Error(requireGoogle?'Google 로그인 구성 준비에 실패했어요. 페이지를 새로고침한 뒤 다시 시도해 주세요.':'안전한 로그인 준비가 끝나지 않았어요. 페이지를 새로고침한 뒤 다시 시도해 주세요.');}
