  function syncLeaderboardUI(){const button=$('secureLeaderboardVisibility'),hint=$('secureLeaderboardVisibilityHint'),switchEl=$('secureLeaderboardSwitch');if(!button)return;const visible=Boolean(account?.leaderboardOptIn);button.setAttribute('aria-checked',String(visible));button.className='flex w-full items-center justify-between border px-3 py-2.5 text-left transition '+(visible?'border-sky-600 bg-sky-950/40':'border-gray-700 bg-[#10141c]');if(hint){hint.textContent=visible?'닉네임과 점수가 전체 랭킹에 공개돼요.':'닉네임과 점수를 공개하지 않아요.';hint.className='mt-0.5 block text-[9px] '+(visible?'text-sky-300':'text-gray-500');}if(switchEl){switchEl.className='relative h-5 w-9 shrink-0 rounded-full transition '+(visible?'bg-sky-500':'bg-gray-700');const knob=switchEl.firstElementChild;if(knob)knob.className='absolute left-0.5 top-0.5 h-4 w-4 rounded-full bg-white transition-transform '+(visible?'translate-x-4':'');}}
  async function toggleLeaderboardVisibility(){if(!account)return;const before=Boolean(account.leaderboardOptIn);account={...account,leaderboardOptIn:!before};syncLeaderboardUI();try{await save(true,true);syncLeaderboardUI();toast(before?'전체 랭킹 공개를 숨겼어요.':'닉네임과 점수를 전체 랭킹에 공개했어요.');}catch(error){account={...account,leaderboardOptIn:before};syncLeaderboardUI();alertError(error);}}  async function request(url,body,auth){const user=auth?.currentUser;if(!user)throw new Error('로그인 준비 중이에요. 잠시 후 다시 시도해 주세요.');const token=await user.getIdToken();const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify(body)});const data=await res.json().catch(()=>null);if(!res.ok||!data?.ok){const msg=data?.error?.message||'요청을 처리하지 못했어요. 다시 시도해 주세요.';const details=data?.error?.details?` [${data.error.details}]`:'';const err=new Error(msg+details);if(data?.error?.code)err.code=data.error.code;throw err;}return data;}  function show(id){const el=$(id);if(el){el.classList.remove('hidden');el.classList.add('flex');}}
