  function state(){const combatPower=Number(window.getPlayerCombatPower?.()||0);const data={...gameState,combatPower:Number.isFinite(combatPower)?Math.max(0,Math.floor(combatPower)):0};['password','schoolName','classNum','studentNum','name','uid','wordsPool','currentQuizCorrectAnswer','assignedWordPackId','assignedWordPackIds','assignedQuestionTypes','activeGuildName','activeGuildLogoUrl'].forEach(key=>delete data[key]);return data;}
