  function welcomeMarkup(){return `<div id="secureWelcomeModal" class="fixed inset-0 z-[99999] flex items-center justify-center bg-[#050506] p-6 text-white"><button id="secureWelcomeTeacher" class="absolute left-6 top-6 flex items-center gap-2 border border-sky-500/70 bg-sky-950/40 px-4 py-2 text-xs font-bold text-sky-300 transition hover:bg-sky-900/60"><i data-lucide="graduation-cap" class="w-4 h-4"></i>교사 로그인</button><div id="secureWelcomeContent" class="flex w-full max-w-sm flex-col items-center text-center" style="display:flex;position:relative;z-index:1;width:min(100%,24rem);flex-direction:column;align-items:center;text-align:center;"><h1 style="margin:0 0 .35rem;color:#facc15;font-size:2rem;line-height:1;font-weight:900;letter-spacing:.04em;text-shadow:0 0 14px rgba(250,204,21,.42);">VOCA HERO!</h1><p style="margin:0 0 1.25rem;color:#d1d5db;font-size:.78rem;font-weight:700;">영단어 용사 키우기</p><img src="media/logo_v2.webp" alt="Voca Hero! 영단어 용사 키우기" class="mb-7 w-56 max-w-[70vw] object-contain drop-shadow-[0_0_24px_rgba(59,130,246,0.32)]"><div class="flex w-full flex-col gap-3"><button id="secureWelcomeStart" style="display:block;width:100%;padding:1rem;background:#e22718;color:#fff;font-weight:800;" class="w-full bg-[#e22718] py-4 text-base font-extrabold text-white transition hover:bg-red-500">시작하기</button><button id="secureWelcomeGoogle" style="display:flex;width:100%;align-items:center;justify-content:center;gap:.5rem;padding:.875rem;border:1px solid #53b5ee;color:#53b5ee;font-weight:700;" class="w-full border border-[#53b5ee] py-3.5 text-sm font-bold text-[#53b5ee] transition hover:bg-sky-950/40"><img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" width="18" height="18" alt="" aria-hidden="true">이어하기 (Google로 로그인)</button></div><a href="/privacy.html" target="_blank" rel="noopener noreferrer" class="mt-4 text-[9px] font-bold text-gray-600 underline hover:text-gray-300">개인정보 처리·계정 삭제 안내</a></div></div>`;}
  function migrationNoticeMarkup(){return `<div id="secureMigrationNotice" class="fixed inset-0 z-[100002] hidden items-center justify-center bg-black/80 p-5 text-white backdrop-blur-sm"><section class="w-full max-w-md border border-yellow-500/70 bg-[#100a24] p-6 shadow-[0_0_36px_rgba(168,85,247,.34)]"><div class="mb-4 flex items-center gap-3"><span class="text-2xl">📜</span><div><h2 class="text-lg font-extrabold text-yellow-300">접속 방법 업데이트</h2><p class="text-[11px] text-violet-200">기존 용사님께 알려드려요</p></div></div><div class="space-y-3 text-sm leading-relaxed text-gray-200"><p>기존 게임 기록이 있다면 <b class="text-white">시작하기</b>를 누른 뒤 <b class="text-sky-300">기존 게임 기록 가져오기</b>에서 예전 기록을 불러와 주세요.</p><p>이전 <b class="text-white">학교·반·번호·이름</b>은 기존 기록을 찾을 때 한 번만 사용하며, 새 게임 계정에는 더 이상 수집하거나 저장하지 않아요.</p><p class="border border-violet-500/50 bg-violet-950/30 p-3 text-violet-100">✨ 기록을 찾은 뒤에는 <b>설정에서 Google 계정을 연동</b>해 주세요. 다른 기기에서도 영웅의 영혼석에 각인된 모험 기록으로 간편하게 접속할 수 있어요.</p></div><div class="mt-5 flex flex-col gap-2"><button id="secureMigrationNoticeClose" class="w-full bg-[#6d3cf2] py-3 font-bold text-white">확인</button><button id="secureMigrationNoticeDismiss" class="w-full border border-gray-600 py-2 text-xs font-bold text-gray-300 hover:bg-white/10">더 이상 보지 않기</button></div></section></div>`;}
