  function renderGuildTrialHistoryTable(activeTrial){
    const table=$('secureGuildTrialHistoryTable'),list=$('secureGuildTrialHistoryList');
    if(!table||!list)return;
    if(!activeTrial){table.classList.add('hidden');return;}
    table.classList.remove('hidden');
    list.replaceChildren();
    const history=Array.isArray(activeTrial.attemptHistory)?activeTrial.attemptHistory:[];
    const maxAttempts=Number(activeTrial.maxAttempts||3);
    const totalQuestions=Number(activeTrial.questionCount||0);
    const currentAttempt=Number(activeTrial.attemptCount||0)+1;
    for(let attemptNo=1;attemptNo<=maxAttempts;attemptNo++){
      const record=history.find(h=>Number(h.attemptNo)===attemptNo);
      const row=document.createElement('tr');
      row.className='hover:bg-[#1a1122] transition-colors';
      const cellNo=document.createElement('td');
      cellNo.className='py-1.5 px-2 font-bold text-gray-300';
      cellNo.textContent=`${attemptNo}회차`;
      const cellCorrect=document.createElement('td');
      cellCorrect.className='py-1.5 px-2 font-semibold text-gray-200';
      const cellAccuracy=document.createElement('td');
      cellAccuracy.className='py-1.5 px-2 font-bold';
      const cellHint=document.createElement('td');
      cellHint.className='py-1.5 px-2 text-gray-300';
      const cellStatus=document.createElement('td');
      cellStatus.className='py-1.5 px-2 font-bold text-[9px]';
      if(record){
        cellCorrect.textContent=`${record.correctCount??0}/${record.questionCount||totalQuestions}`;
        const acc=Number(record.accuracy||0).toFixed(0);
        cellAccuracy.textContent=`${acc}%`;
        if(Number(acc)>=100)cellAccuracy.className+=' text-emerald-300';
        else if(Number(acc)>=70)cellAccuracy.className+=' text-yellow-300';
        else cellAccuracy.className+=' text-rose-300';
        cellHint.textContent=record.hintsUsed>0?`${record.hintsUsed}회`:'미사용';
        if(record.overcome||Number(acc)>=100){
          cellStatus.textContent='극복! 🎉';
          cellStatus.className+=' text-emerald-300';
        }else{
          cellStatus.textContent='기록 완료';
          cellStatus.className+=' text-gray-400';
        }
      }else{
        cellCorrect.textContent='-';
        cellAccuracy.textContent='-';
        cellAccuracy.className+=' text-gray-500';
        cellHint.textContent='-';
        if(!activeTrial.overcome&&!activeTrial.exhausted&&attemptNo===currentAttempt){
          cellStatus.textContent='도전 가능';
          cellStatus.className+=' text-amber-300 font-extrabold';
        }else{
          cellStatus.textContent='대기';
          cellStatus.className+=' text-gray-600';
        }
      }
      row.append(cellNo,cellCorrect,cellAccuracy,cellHint,cellStatus);
      list.append(row);
    }
  }
