  function renderGuildTrialQuestion(){const state=guildTrialState;if(!state)return;const question=state.questions[state.current],area=$('secureGuildTrialQuestionArea'),result=$('secureGuildTrialRoundResult'),choices=$('secureGuildTrialChoices'),inputArea=$('secureGuildTrialInputArea'),input=$('secureGuildTrialInput'),feedback=$('secureGuildTrialFeedback'),prompt=$('secureGuildTrialPrompt');area.classList.remove('hidden');result.classList.add('hidden');guildTrialAnswerLocked=false;state.selectedAnswer='';state.orderAnswer='';feedback.textContent='';choices.replaceChildren();inputArea.classList.add('hidden');inputArea.classList.remove('flex');input.value='';input.readOnly=false;prompt.onclick=null;prompt.removeAttribute('role');prompt.removeAttribute('tabindex');prompt.classList.remove('cursor-pointer','text-sky-300');prompt.textContent=String(question.prompt||'문제를 불러오지 못했어요.');$('secureGuildTrialCounter').textContent=`${state.attemptNo}회차 · ${state.current+1}/${state.questions.length}`;$('secureGuildTrialType').textContent=trialTypeLabel(question.type);$('secureGuildTrialProgress').style.width=Math.round((state.current/state.questions.length)*100)+'%';if(question.speakText){prompt.textContent='🔊 발음 듣기';prompt.role='button';prompt.tabIndex=0;prompt.classList.add('cursor-pointer','text-sky-300');prompt.onclick=()=>speakGuildTrialPrompt(question.speakText);prompt.onkeydown=(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();speakGuildTrialPrompt(question.speakText);}};}else prompt.onkeydown=null;if(Array.isArray(question.letters)&&question.letters.length){choices.className='flex flex-wrap items-center justify-center gap-2 my-4 min-h-[52px] p-3 bg-[#121016] border border-[#2e1d28]';question.letters.forEach(letter=>{const button=document.createElement('button');button.type='button';button.className='flex h-11 w-11 shrink-0 items-center justify-center border border-[#444] bg-[#1a1822] text-lg font-black uppercase text-white hover:border-rose-400 focus:outline-none transition rounded-none';button.textContent=letter;button.onclick=()=>selectGuildTrialLetter(letter,button);choices.append(button);});inputArea.classList.remove('hidden');inputArea.classList.add('flex');input.readOnly=true;let clearBtn=$('secureGuildTrialClearLetters');if(!clearBtn){clearBtn=document.createElement('button');clearBtn.id='secureGuildTrialClearLetters';clearBtn.type='button';clearBtn.className='border border-amber-600 bg-amber-950/40 px-3 text-xs font-bold text-amber-200 hover:border-amber-300';clearBtn.textContent='지우기';clearBtn.onclick=()=>resetGuildTrialLetters();$('secureGuildTrialSubmit')?.before(clearBtn);}clearBtn.classList.remove('hidden');}else if(Array.isArray(question.options)&&question.options.length){choices.className='grid grid-cols-2 gap-2 my-4';$('secureGuildTrialClearLetters')?.classList.add('hidden');question.options.forEach(option=>{const button=document.createElement('button');button.type='button';button.dataset.optionId=String(option.id||'');button.className='border border-[#3c3c3c] bg-[#151515] p-3 text-xs font-bold text-white hover:border-rose-400';button.textContent=formatGuildTrialEnglish(option.label);button.onclick=()=>selectGuildTrialAnswer(option.id,button);choices.append(button);});const submit=document.createElement('button');submit.type='button';submit.className='col-span-2 mt-2 border border-rose-500 bg-rose-950/50 p-3 text-xs font-black text-rose-100';submit.textContent='정답 제출';submit.onclick=()=>answerGuildTrial();choices.append(submit);}else{choices.className='grid grid-cols-2 gap-2 my-4';$('secureGuildTrialClearLetters')?.classList.add('hidden');inputArea.classList.remove('hidden');inputArea.classList.add('flex');setTimeout(()=>input.focus(),50);}updateGuildTrialHintText();}
  async function answerGuildTrial(){if(guildTrialAnswerLocked||!guildTrialState)return;const state=guildTrialState,question=state.questions[state.current],input=$('secureGuildTrialInput'),isChoice=Array.isArray(question.options)&&question.options.length,rawAnswer=isChoice?state.selectedAnswer:input.value;if(!rawAnswer){toast(isChoice?'답을 먼저 선택해 주세요.':'⚠️ 영단어를 입력해 주세요.');return;}if(!isChoice&&!question.letters?.length&&window.formatVocaEnglishInput&&!window.formatVocaEnglishInput(input))return;const answer=String(rawAnswer).trim(),key=guildTrialQuestionKey(question);guildTrialAnswerLocked=true;state.answers.set(key,{questionId:key,answer});document.querySelectorAll('#secureGuildTrialChoices button').forEach(button=>{button.disabled=true;});updateGuildTrialHintText();try{const {progress}=await request(studentApi,{action:'guildTrialEvent',trialId:state.trial.id,event:'answer',attemptId:state.attemptId,questionKey:key,answer},window._fbAuth),answerResult=progress?.answerResult||{},correct=answerResult.correct===true,feedback=$('secureGuildTrialFeedback');feedback.textContent=correct?'정답입니다!':`오답입니다. 정답은 ${formatGuildTrialEnglish(answerResult.correctAnswer||'')}입니다.`;feedback.className='mt-3 min-h-8 text-center text-xs font-black '+(correct?'text-emerald-300':'text-rose-300');setTimeout(()=>{state.current+=1;if(state.current>=state.questions.length)finishGuildTrialRound();else renderGuildTrialQuestion();},900);}catch(error){guildTrialAnswerLocked=false;updateGuildTrialHintText();alertError(error);}}
  async function closeGuildTrialAndRefresh(){hide('secureGuildTrialModal');guildTrialState=null;await loadGuildOverview();}
  async function finishGuildTrialRound(){const state=guildTrialState,area=$('secureGuildTrialQuestionArea'),result=$('secureGuildTrialRoundResult'),action=$('secureGuildTrialAction');area.classList.add('hidden');result.classList.remove('hidden');action.disabled=true;$('secureGuildTrialResultTitle').textContent='시련 결과 기록 중...';$('secureGuildTrialResultText').textContent='이번 도전의 정답과 힌트 사용 기록을 영혼석에 새기고 있어요.';try{const answers=[...state.answers.values()];const {completion}=await request(studentApi,{action:'completeGuildTrial',trialId:state.trial.id,attemptId:state.attemptId,answers},window._fbAuth);const attempt=completion.result||{},accuracy=Number(attempt.accuracy||0).toFixed(1),hintRate=attempt.hintsUsed?Math.round(Number(attempt.correctAfterHint||0)/attempt.hintsUsed*100):null,unassistedRate=attempt.unassistedTries?Math.round(Number(attempt.unassistedCorrect||0)/attempt.unassistedTries*100):null;if(completion.overcome){$('secureGuildTrialResultTitle').textContent='시련 극복!';$('secureGuildTrialResultText').textContent=`${attempt.attemptNo}회차 정답률 ${accuracy}% · ${attempt.questionCount}문제를 모두 맞혔어요. ${completion.rewardGuildCoins} 길드 코인을 획득했습니다.${attempt.hintsUsed?` 힌트 사용 문제 정답률 ${hintRate}% · 무힌트 정답률 ${unassistedRate??0}%`:''}`;action.textContent='길드 본부로 돌아가기';}else if(completion.exhausted){$('secureGuildTrialResultTitle').textContent=`${attempt.attemptNo}회차 · 정답률 ${accuracy}%`;$('secureGuildTrialResultText').textContent=`도전 3회를 모두 사용했어요. 힌트 ${attempt.hintsUsed}문제 · 힌트 사용 문제 정답률 ${hintRate??0}% · 무힌트 정답률 ${unassistedRate??0}% 기록이 학습 분석에 반영됐어요.`;action.textContent='길드 본부로 돌아가기';}else{$('secureGuildTrialResultTitle').textContent=`${attempt.attemptNo}회차 · 정답률 ${accuracy}%`;$('secureGuildTrialResultText').textContent=`${attempt.correctCount}/${attempt.questionCount} 정답 · 힌트 ${attempt.hintsUsed}문제${attempt.hintsUsed?`(힌트 사용 문제 정답률 ${hintRate}%)`:''} · 무힌트 정답률 ${unassistedRate??0}%. 남은 도전 ${completion.remainingAttempts}회는 길드 본부에서 전체 문제를 새로 풀 수 있어요.`;action.textContent='길드 본부로 돌아가기';}action.disabled=false;action.onclick=closeGuildTrialAndRefresh;}catch(error){$('secureGuildTrialResultTitle').textContent='진행 기록 저장 실패';$('secureGuildTrialResultText').textContent='인터넷 연결을 확인한 뒤 다시 저장해 주세요.';action.textContent='다시 저장';action.disabled=false;action.onclick=finishGuildTrialRound;alertError(error);}}
  async function useGuildTrialHint(){const state=guildTrialState;if(!state||guildTrialAnswerLocked)return;const question=state.questions[state.current],questionKey=guildTrialQuestionKey(question);if(state.hintedWords.has(questionKey))return;const button=$('secureGuildTrialHint');button.disabled=true;try{const {progress}=await request(studentApi,{action:'guildTrialEvent',trialId:state.trial.id,event:'hint',attemptId:state.attemptId,questionKey},window._fbAuth);state.hintedWords.add(questionKey);const hint=progress?.hint||{};if(hint.kind==='choice-eliminate'){const hidden=new Set(Array.isArray(hint.hideOptionIds)?hint.hideOptionIds.map(String):[]);[...$('secureGuildTrialChoices').children].filter(choice=>hidden.has(String(choice.dataset.optionId||''))).forEach(choice=>choice.classList.add('hidden'));$('secureGuildTrialFeedback').textContent='힌트: 오답 보기 두 개를 지웠어요.';}else{$('secureGuildTrialFeedback').textContent=`힌트: 첫 글자 ${String(hint.firstLetter||'?')} · 영문 ${Number(hint.letterCount||0)}글자`;$('secureGuildTrialInput')?.focus();}$('secureGuildTrialFeedback').className='mt-3 min-h-8 text-center text-xs text-sky-300';updateGuildTrialHintText();}catch(error){alertError(error);button.disabled=false;}}
  async function beginGuildTrial(trial){if(!trial||!trial.canAttempt||guildTrialState)return;try{const {progress}=await request(studentApi,{action:'guildTrialEvent',trialId:trial.id,event:'start'},window._fbAuth);if(progress.completed){pendingGuildTrial=null;await loadGuildOverview();return;}if(progress.exhausted){toast('이번 시련의 도전 기회를 모두 사용했어요.');await loadGuildOverview();return;}const questions=Array.isArray(progress.questions)?progress.questions:[];if(!progress.attemptId||!questions.length)throw new Error('시련 문제를 안전하게 불러오지 못했어요. 다시 시도해 주세요.');guildTrialState={trial,questions,current:0,attemptNo:Number(progress.attemptCount||trial.attemptCount||0)+1,attemptId:progress.attemptId,answers:new Map(),hintedWords:new Set()};$('secureGuildTrialTitle').textContent=(trial.guildName||'길드')+' · 오답 정복 시련';$('secureGuildTrialReward').textContent=`${guildTrialState.attemptNo}/${trial.maxAttempts||3}회차 · 극복 보상 ${trial.rewardGuildCoins} 길드 코인`;const scene=$('secureGuildTrialScene');if(scene)scene.src=trial.sceneImage||'/media/test/test1.webp?v=20260810-1';show('secureGuildTrialModal');renderGuildTrialQuestion();}catch(error){alertError(error);}}

  window._secureStudentSave=(quiet=true)=>save(quiet);
  window.openPendingGuildTrial=()=>{const offline=$('offlineRewardModal');if(!pendingGuildTrial?.mustForce||!pendingGuildTrial?.canAttempt||(offline&&!offline.classList.contains('hidden')))return false;beginGuildTrial(pendingGuildTrial);return true;};
  function profileInput(){return {nickname:$('secureNickname').value,learningGrade:Number($('secureGrade').value),leaderboardOptIn:$('secureLeaderboardOptIn').checked,privacyConsent:$('securePrivacyConsent').checked};}
  function beginGameEntry(message='✨ 영혼석에서 모험 기록을 불러오는 중...'){['secureWelcomeModal','secureStudentModal','loginModal','pinVerifyModal','newUserRegisterModal'].forEach(hide);if(typeof window.showGameLoadingOverlay==='function')window.showGameLoadingOverlay(message);}
  function cancelGameEntry(returnTo='secureWelcomeModal'){if(typeof window.hideGameLoadingOverlay==='function')window.hideGameLoadingOverlay();if(returnTo)show(returnTo);}
  function restoreMigrationForm(){cancelGameEntry('secureStudentModal');const main=$('secureStudentMainPanel'),migration=$('secureMigrationPanel');if(main)main.style.display='none';if(migration){migration.style.display='flex';migration.style.flexDirection='column';migration.style.gap='1rem';}}
  async function withAssignedWordPack(data){try{const {assignment}=await request(studentApi,{action:'loadAssignedWordPack'},window._fbAuth);const ids=Array.isArray(assignment?.wordPackIds)?assignment.wordPackIds.filter(Boolean):(assignment?.wordPackId?[assignment.wordPackId]:[]);return {...data,activeGuildName:assignment?.classLabel||data.activeGuildName||null,activeGuildLogoUrl:assignment?.guildLogoUrl||data.activeGuildLogoUrl||null,assignedWordPackId:ids[0]||null,assignedWordPackIds:ids,assignedQuestionTypes:Array.isArray(assignment?.questionTypes)&&assignment.questionTypes.length?assignment.questionTypes:['meaning-choice']};}catch(error){console.warn('Assigned word pack unavailable:',error);return {...data,activeGuildName:data.activeGuildName||null,activeGuildLogoUrl:data.activeGuildLogoUrl||null,assignedWordPackId:null,assignedWordPackIds:[],assignedQuestionTypes:['meaning-choice']};}}
  async function start(){if(!$('securePrivacyConsent').checked){alertError(new Error('학습 기록 저장 안내에 동의해야 시작할 수 있어요.'));return;}let entering=false;try{const auth=await activeStudentAuth();beginGameEntry('✨ 새로운 영혼석을 준비하는 중...');entering=true;const {account:data}=await request(studentApi,{action:'create',...profileInput()},auth);clearLegacy();apply(await withAssignedWordPack(data));toast('✨ 새로운 영웅의 영혼에 이름이 각인되었습니다! 모험을 시작해요!');}catch(error){if(entering)cancelGameEntry('secureStudentModal');alertError(error);}}
  async function signInStudentGoogle(){let entering=false;try{const auth=await activeStudentAuth(true);if(account&&auth.currentUser?.isAnonymous)throw new Error('현재 기기에서 만든 진행 상황은 설정의 “Google 계정으로 진행 상황 보호하기”로 연결해 주세요.');await window._signInWithPopup(auth,window._fbStudentGoogleProvider);beginGameEntry('✨ Google 영혼석에서 모험 기록을 찾는 중...');entering=true;const {account:data}=await request(studentApi,{action:'load'},auth);if(data){clearLegacy();apply(await withAssignedWordPack(data));toast('Google에 저장된 진행 상황을 불러왔어요.');}else{$('secureNickname').value=nickname();chooseGoogleNoRecord();}}catch(error){if(entering)cancelGameEntry('secureWelcomeModal');alertError(error);}}
  async function finishStudentGoogleLink(){let auth=null,prepared=false;try{auth=await activeStudentAuth(true);const sourceUser=auth.currentUser,sourceUid=sourceUser?.uid;if(!sourceUser||!sourceUid)throw new Error('현재 게임 기록을 확인하지 못했어요.');await save(true,true);await request(studentApi,{action:'prepareGoogleLink'},auth);prepared=true;try{await window._fbLinkWithPopup(auth,window._fbStudentGoogleProvider);await auth.currentUser?.getIdToken(true);await request(studentApi,{action:'markGoogleLinked'},auth);prepared=false;syncStudentAuthUI();toast('Google 계정 연결이 완료됐어요. 다른 기기에서도 이어할 수 있어요.');}catch(error){if(error?.code!=='auth/credential-already-in-use')throw error;const sourceToken=await sourceUser.getIdToken(true);await window._signInWithPopup(auth,window._fbStudentGoogleProvider);const {account:data}=await request(studentApi,{action:'claimGoogleLink',sourceUid,sourceToken},auth);prepared=false;clearLegacy();apply(await withAssignedWordPack(data));syncStudentAuthUI();window.showAlert?.('이전 버전의 Google 연결 기록을<br><b>새 보안 계정 연결로 안전하게 옮겼어요.</b><br><br>이제 다른 기기에서도 Google로 이어할 수 있어요.','G','Google 연결 완료');}}catch(error){if(prepared&&auth?.currentUser?.isAnonymous){try{await request(studentApi,{action:'markGoogleUnlinked'},auth);}catch{}}alertError(error);}}
  function linkStudentGoogle(){if(!account)return alertError(new Error('먼저 용사를 만들거나 기존 진행 상황을 불러와 주세요.'));if(studentGoogleLinked()){toast('이 진행 상황은 이미 Google 계정으로 보호되고 있어요.');return;}const message='Google 계정은 이 게임 기록을 다른 기기에서 이어하기 위해서만 사용해요. 게임 데이터베이스에는 Google 이메일을 저장하지 않아요.';if(typeof window.showConfirm==='function')window.showConfirm(message,finishStudentGoogleLink,null,{icon:'G',title:'Google로 진행 상황 보호',yesLabel:'연결하기',noLabel:'취소'});else finishStudentGoogleLink();}
  async function finishStudentGoogleUnlink(){try{const auth=await activeStudentAuth(true),beforeUid=auth.currentUser?.uid;if(!beforeUid||!studentGoogleLinked())throw new Error('연결된 Google 계정을 찾지 못했어요.');await save(true,true);try{await window._fbUnlink(auth.currentUser,'google.com');}catch(error){if(error?.code!=='auth/requires-recent-login')throw error;await window._fbReauthenticateWithPopup(auth.currentUser,window._fbStudentGoogleProvider);await window._fbUnlink(auth.currentUser,'google.com');}if(!auth.currentUser||auth.currentUser.uid!==beforeUid)throw new Error('연결 해제 후 현재 기기의 게스트 계정을 확인하지 못했어요. 안전을 위해 페이지를 닫지 말고 새로고침해 주세요.');await auth.currentUser.getIdToken(true);await request(studentApi,{action:'markGoogleUnlinked'},auth);syncStudentAuthUI();window.showAlert?.('Google 계정 연결을 해제했어요.<br><br><span class="text-yellow-200">이 용사의 기록은 이제 이 기기에서만 이어할 수 있어요.</span><br>브라우저 데이터 삭제·기기 변경 전에는 다시 Google에 연결해 주세요.<br><br>이제 다른 게스트 계정에서 같은 Google 계정을 연결할 수 있어요.','G','Google 연결 해제 완료');}catch(error){alertError(error);}}
  function unlinkStudentGoogle(){if(!studentGoogleLinked()){toast('현재 Google 계정과 연결되어 있지 않아요.');return;}const message='연결을 해제하면 이 용사의 기록은 현재 기기에서만 이어할 수 있어요.<br><br><b class="text-red-200">브라우저 데이터 삭제, 기기 변경 또는 로그아웃 뒤에는 이 기록에 다시 들어오지 못할 수 있어요.</b><br><br>Google 계정 본인 확인 후 연결을 해제할까요?';if(typeof window.showConfirm==='function')window.showConfirm(message,finishStudentGoogleUnlink,null,{icon:'!',title:'Google 연결 해제',yesLabel:'연결 해제',noLabel:'취소'});else finishStudentGoogleUnlink();}
  async function studentLogout(){const logout=async()=>{try{await save(true,true);await window._fbSignOut(window._fbAuth);account=null;localStorage.removeItem(studentAccountMarker);localStorage.setItem(studentAutoEntrySkip,'1');clearLegacy();location.reload();}catch(error){alertError(error);}};if(studentGoogleLinked()){await logout();return;}const message='Google 계정에 연동되지 않은 영웅의 영혼은 로그아웃하면 다시 찾지 못합니다.<br><br>그래도 로그아웃하시겠습니까?';if(typeof window.showConfirm==='function')window.showConfirm(message,logout,null,{icon:'⚠️',title:'연동되지 않은 영웅',yesLabel:'로그아웃',noLabel:'취소'});else if(window.confirm('Google 계정에 연동되지 않은 영웅의 영혼은 다시 찾지 못합니다. 그래도 로그아웃하시겠습니까?'))await logout();}
  async function migrate(){const school=$('legacySchool');if(!school?.dataset.selected){alertError(new Error('학교명을 검색한 뒤, 목록에서 학교를 선택해 주세요.'));return;}try{const credentials={schoolName:school.dataset.selected,grade:Number($('legacyGrade').value),classNum:Number($('legacyClass').value),studentNum:Number($('legacyNumber').value),name:$('legacyName').value};beginGameEntry('✨ 영혼석에 잠든 모험 기록을 되찾는 중...');const {account:data}=await request(studentApi,{action:'migrateLegacy',...profileInput(),credentials,pin:$('legacyPin').value},await activeStudentAuth());clearAllLegacy();apply(await withAssignedWordPack(data));toast('✨ 영혼석에 잠들어 있던 모험 기록을 되찾았어요!');}catch(error){restoreMigrationForm();alertError(error);}}
