        reportMetric('길드 기여',Number(report.guildPoints||0).toLocaleString()+'점','text-yellow-300'),
        reportMetric('시련 도전 / 재도전',Number(report.trialAttempts||0)+' / '+Number(report.trialRetries||0)+'회','text-rose-300'),
        reportMetric('힌트 사용 문제 정답률',Number(hinted.accuracy||0).toFixed(1)+'% · '+Number(hinted.correct||0)+'/'+Number(hinted.tries||0),'text-violet-300'),
        reportMetric('무힌트 문제 정답률',Number(unassisted.accuracy||0).toFixed(1)+'% · '+Number(unassisted.correct||0)+'/'+Number(unassisted.tries||0),'text-cyan-300')
