    const target=applyAll?'현재 전체 길드원과 향후 가입자':memberIds.length+'명의 선택 길드원';if(window.showConfirm)window.showConfirm(target+'에게 선택한 단어팩과 문제 유형을 적용할까요?',execute,null,{icon:'📚',title:'학습 설정 저장',yesLabel:'설정 적용',noLabel:'취소'});else execute();
